def calc():
 ctx.prec=512
 base={'ROOT':ROOT};exec(CORE,base)
 def run(name,initial=None):
  ns=dict(base if initial is None else initial);exec(BLOCKS[name],ns);return ns
 near=run('near');bg=run('background');coord=run('coordinate_base')
 seed=run('seed',coord);far=run('remaining_far',coord)
 mixed=run('mixed');remote=run('remote');endpoint=run('endpoint')
 H=base['H'];sig=base['sig'];K=base['K'];p=base['pars'];S=base['S']
 nval=near['pref']*near['near']
 fourth_m=100*arb('4.04')*max(arb(1),2**(8-sig))*arb('.004')*H**3*(mixed['K'][0]*mixed['reg']+mixed['SG'][0]*mixed['P'][0])
 mixed_total=mixed['eta']+fourth_m
 a=arb('.01');b=arb('.02');N=arb(1801)/arb(2).sqrt()
 zn=lambda v:a**v/(2*v).sqrt()
 moment=2*2**(sig+1)/(sig+1)*arb('.24')**(-5)*zn(arb(3))+(2**5+1)*b**(sig-4)/(sig-4)*zn(7-sig)
 fourth_r=100*arb('4.04')*10*remote['Kj'][0]*N*moment
 remote_total=sum(remote['by'],arb(0))+fourth_r
 ca=(p['beta']*p['C']).log()/2-(arb(p['q'])+1).digamma()/2+arb.const_euler()/2-arb(31)/30
 check('frozen_finite_Mellin_constant',abs(ca)<5)
 check('whole_phase_recurrence_no_root_gap',(1+arb('4.01')/40)**5-1<1)
 check('outer_background_support_inside_phase',arb('3.9')*H*arb('1.001')<arb('.02'))
 check('all_exponential_background_orders',bg['exp_tame']<2 and 14*bg['Wb']<1)
 comp=5+225*(1+arb(9).log()/arb(2).log())+900*arb(18).log()**2
 check('background_log_composition_guard',comp<10000 and 19*10000*8<2048**2)
 check('background_top_pullback_guard',(arb('5.01')+arb('1.01'))*arb(5).sqrt()<32)
 check('uniform_Bcap',bg['Bcap']<arb('2.062e30'))
 check('background_budget_contribution',arb('8.123e-26')*arb('2.062e30')<167500)
 check('near_complete_subtracted_symbol',nval<7368340000)
 check('seed_returned_local_finite_polynomial',seed['normal_local']<arb('.003509'))
 check('seed_returned_Omega_polynomial',seed['omega_local']<arb('.000041791'))
 check('seed_coordinate_near',seed['coordnear']<arb('2.4e-8'))
 check('seed_coordinate_far',far['coordfar']<arb('4.775e-18'))
 check('seed_density_near_and_far',seed['density_near']<arb('2.248e-15') and seed['density_far']<arb('1.220e-27'))
 check('whole_auxiliary_normal_tail',seed['normal_tail']<arb('1.446e-25'))
 check('whole_angular_spectral_far',far['spectralfar']<arb('7.517e-15'))
 check('mixed_metric_germ_flow',arb('6.01')*arb('2.21')<14 and 2*arb('6.01')*arb('1.1')<14 and 2*arb('.004').exp()*arb('1.1')/p['beta'].sqrt()<arb('5.5'))
 check('mixed_metric_germ_displacement',arb(14)/160+arb('.001')/arb('.499')<arb('.1'))
 check('mixed_metric_two_arm_exponent',4*72*100==18*10*160 and arb('.18').exp()<arb('1.2'))
 check('mixed_metric_full_return',mixed_total<arb('.23002') and fourth_m>0)
 check('mixed_metric_fast_debit',arb('.23002')*arb('5.681e9')<1306750000)
 check('remote_input_full_return',remote_total<arb('.00453') and fourth_r>0)
 check('remote_input_fast_debit',arb('.00453')*arb('5.681e9')<25740000)
 check('entire_actual_far_two_parameter_rate',endpoint['rate']>arb('1.96'))
 check('entire_actual_far_strong_return',endpoint['eta']<arb('.24348') and endpoint['fourth']>0)
 check('entire_actual_far_fast_debit',arb('.24348')*arb('5.681e9')<1383220000)
 # Independent exact local Riesz contact and Mellin finite polynomial identities.
 z=S.symbols('z',positive=True);qf=S.Function('q')(z);v=S.Function('v')(z)
 fn=v
 for k in range(4):fn=qf*S.diff(fn,z)
 coeff=S.expand(fn/qf**2).coeff(S.diff(v,z,3))
 check('Riesz_diagonal_contact_matches_actual_Ds4',S.simplify(coeff-6*qf*S.diff(qf,z))==0)
 ss,hm,lz,ca0,km=S.symbols('s H logz cA kM')
 pp=ss*(ss-1)*(ss-2)*(ss-3);rr=ss*(ss-1)*(2*ss-5)
 lhs=-(ss-4)*pp*(hm-1/(ss-3)-1/(ss-2)-lz+ca0-km)+pp
 rhs=-(ss-4)*pp*hm+(lz+km-ca0)*(ss-4)*pp+(ss-4)*rr+pp
 check('Mellin_full_finite_polynomial',S.cancel(lhs-rhs)==0)
 seed_sum=sum(map(arb,['.003138','.000142','.01755','.003509','.000041791','2.4e-8','4.775e-18','2.248e-15','1.220e-27','1.446e-25','8.424e-10','7.517e-15','.00453','2e-6','4.001e-9']),arb(0))
 third_sum=sum(map(arb,['7368340000','521282000','167500','99710000','1306750000','25740000','1383220000','.001253','1e-1000']),arb(0))
 check('complete_seed_allowance',seed_sum<arb('.028913'))
 check('complete_third_allowance',third_sum<arb('1.0706e10'))
 screen=arb('.028913')+arb('1e-11')*arb('1.0706e10')
 check('conditional_requested_screen',screen<arb('.1599164'))
 coarse=nval*9/(arb(74)/(5*arb.pi()))
 coarse_screen=seed_sum+arb('1e-11')*(third_sum-7368340000+coarse)
 check('coarse_estimator_does_not_certify',coarse_screen>arb('.1599164'))
 check('unbounded_C5_to_graph_packet_power',8-5==3 and K>0)
 return dict(outcome='certified_bound_on_stated_admitted_fast_family',actual_complete_strong_bound_executed=True,
  eta_seed_upper='.028913',C3_upper='1.0706e10',screen_upper='.135973',screen_reserve='.0239434',conditional_screen_certified=True,
  seed_ledger_sum=old.encoded(seed_sum),third_ledger_sum=old.encoded(third_sum),
  coarse_estimator_allowance=old.encoded(coarse),coarse_complete_screen=old.encoded(coarse_screen),
  near_third=old.encoded(nval),Bcap=old.encoded(bg['Bcap']),background_parts=bg['ans'],
  returned_seed={k:old.encoded(seed[k]) for k in ['normal_local','omega_local','coordnear','density_near','density_far','normal_tail']},
  coordinate_far=old.encoded(far['coordfar']),spectral_far=old.encoded(far['spectralfar']),
  mixed_metric_return=old.encoded(mixed_total),mixed_fourth_vertex=old.encoded(fourth_m),
  remote_return=old.encoded(remote_total),remote_fourth_vertex=old.encoded(fourth_r),
  actual_far_uniform=old.encoded(endpoint['eta']),actual_far_fast_metric=old.encoded(endpoint['eta']*arb('5.681e9')),actual_far_rate=old.encoded(endpoint['rate']),
  phase_scope='m z3+z4(d0+d1 log z+d2 log^2 z)+cslow z^(4+e*)+fast graph radius 1e-11; A<=.001; actual paired domain and bounded charts',
  original_X_admission=False,additional_unbounded_phase_allowed=False,normalization_changed=False,physical_domain_changed=False,
  raw_cutoff_operator_norm_convergence_claimed=False,all_angular_thermal_modes_contacts_boundary_returns_retained=True,
  bare_C5_input_comparison_fails=True,global_stronger_X_comparison_known=False,
  optimistic_alpha_threshold=old.encoded(arb('.001')),optimistic_RX_alpha_threshold=old.encoded(arb('.25')/arb('.028913')),
  optimistic_RX_alpha_squared_threshold=old.encoded(arb('5e7')/arb('1.0706e10')),
  mass_slow_global_A_remaining='.00094319',actual_controlled_solution=False,nonlinear_admission=False,nonlinear_preservation=False,nonlinear_contraction=False,
  exact_compatibility=False,physical_matching=False,validity_noise=False,all_sector_stability=False,construction_obstruction=False,
  projection_reevaluated=False,audit_status='closed',goal_status='active',next_global_source_phase_calculation_executed=False)

def main():
 ctx.prec=512
 review=json.loads((ROOT/OWN[2]).read_bytes())
 prev=json.loads((ROOT/'evidence/current-joint-return-feasibility-attempt.json').read_bytes())['runs'][-1]
 paths=set(OWN+review['retained_inputs'])|set(prev['input_sha256_after'])
 before={p:digest(p) for p in sorted(paths)}
 out=ROOT/'evidence'/f'{STEM}{"-development" if DEVELOPMENT else ""}.json'
 archive=json.loads(out.read_bytes()) if out.exists() else {'runs':[]}
 run=dict(started_utc=datetime.now(timezone.utc).isoformat(),status='running',input_sha256_before=before,
  frozen_sources_utf8={p:(ROOT/p).read_text(encoding='utf-8') for p in OWN},precision_bits=ctx.prec,python=sys.version,invocation=sys.argv)
 archive['runs'].append(run)
 def save():out.write_bytes((json.dumps(archive,indent=2)+'\n').encode())
 save()
 try:
  check('ordinary_argument_frozen',digest(OWN[0])==review['ordinary_argument_sha256'])
  check('previous_scientific_sources_preserved',all(digest(p)==h for p,h in prev['input_sha256_after'].items()))
  run['result']=calc();run['status']='passed'
 except Exception:run['status']='failed';run['exception']=traceback.format_exc()
 finally:
  run['checks']=CHECKS;run['input_sha256_after']={p:digest(p) for p in before}
  if before!=run['input_sha256_after']:run['status']='failed';run['input_changed']=True
  run['finished_utc']=datetime.now(timezone.utc).isoformat();save()
 if not DEVELOPMENT:
  with (ROOT/'evidence'/f'{STEM}.log').open('ab') as f:f.write((json.dumps(run)+'\n').encode())
 result=run.get('result',{})
 print(json.dumps(dict(status=run['status'],checks=len(CHECKS),inputs=len(before),exception=run.get('exception'),eta=result.get('eta_seed_upper'),C3=result.get('C3_upper'),screen=result.get('screen_upper'),reserve=result.get('screen_reserve')),indent=2))
 if run['status']!='passed':raise SystemExit(1)
if __name__=='__main__':main()
